<script setup lang="ts">
import {useParameterTransaction} from './useParameterTransaction';
import SeriesPreview from './SeriesPreview.vue';
import ParameterDialog from './ParameterDialog.vue';
const settingsOpen=ref(false);
import {beginWorkflowActivity} from './workflowActivity';
import {apiError} from './apiError';
import {ref,watch} from 'vue';
const eventCsv=defineModel<string>({required:true});
const props=defineProps<{draftMode?:boolean;projectId:string;csv:string;parameters:Record<string,number>}>();const emit=defineEmits<{apply:[csv:string,id:string,scenarioId?:string]}>();
const scenarioId=ref('');const scenarios=ref<any[]>([]);const start=ref(0);const smooth=ref(false);const ramp=ref(2);const records=ref<any[]>([]);const selected=ref<any>(null);const busy=ref(false);const error=ref('');
async function refresh(){const response=await fetch('/api/production-sequences?project_id='+props.projectId);if(!response.ok)throw Error('读取生产序列失败');records.value=await response.json();const scenarioResponse=await fetch('/api/scenarios?project_id='+props.projectId);if(scenarioResponse.ok)scenarios.value=await scenarioResponse.json()}
watch(()=>props.projectId,()=>{selected.value=null;scenarioId.value='';refresh().catch(e=>error.value=String(e))},{immediate:true});
async function run(){commitSettings(false);busy.value=true;error.value='';const project=props.projectId;const finishProgress=beginWorkflowActivity(project,'scenario');try{const response=await fetch('/api/production-sequences',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:project,background_csv:props.csv,event_csv:eventCsv.value,start_hour:start.value,smooth:smooth.value,ramp_hours:ramp.value,scenario_id:scenarioId.value||null,resource_capacities:{storage_power_kw:props.parameters.storage_power_kw,emergency_gen_kw:props.parameters.emergency_gen_kw,grid_channel_kw:props.parameters.grid_channel_kw}})});const data=await response.json();if(!response.ok)throw Error(apiError(data.detail));if(project===props.projectId){selected.value=data;await refresh()}}catch(e){error.value=String(e)}finally{busy.value=false;finishProgress()}}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(selected.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='生产序列快照.json';a.click();URL.revokeObjectURL(url)}
const commitSettings=useParameterTransaction(settingsOpen,{start,smooth,ramp,scenarioId,eventCsv});
</script>
<template><article><h3>极端事件嵌入背景序列</h3><p>当前工程源荷为背景。事件可粘贴CSV，或从上方窗口分析送入；事件原始时间仅用于顺序校验，嵌入时按背景时间轴重定位。支持2–8760小时背景。</p><button class="settings-trigger" @click="settingsOpen=true">序列嵌入参数</button><ParameterDialog transactional @apply="commitSettings()" v-model:open="settingsOpen" title="序列嵌入参数"><textarea v-model="eventCsv" placeholder="事件CSV：timestamp,load_kw,wind_kw,pv_kw" :disabled="busy"></textarea><label class="field">嵌入起始小时（从0计）<input type="number" min="0" v-model.number="start" :disabled="busy"></label><label><input type="checkbox" v-model="smooth" :disabled="busy"> 开启边界平滑（会修改相邻时段）</label><label v-if="smooth" class="field">平滑时长 / h<input type="number" min="1" max="24" v-model.number="ramp" :disabled="busy"></label><label class="field">事件故障场景<select v-model="scenarioId" :disabled="busy"><option value="">仅嵌入源荷</option><option v-for="scenario in scenarios" :value="scenario.id">{{scenario.name}} · {{scenario.id.slice(0,8)}}</option></select></label><p>故障场景时间轴须与事件CSV一致。事件外容量采用当前工程资源值；修改资源后需重新生成耦合序列。</p><button class="primary" @click="run" :disabled="busy||!eventCsv||!projectId">{{busy?'正在嵌入并保存…':'构建并保存生产序列'}}</button><p v-if="error" class="error">{{error}}</p></ParameterDialog><h3>已保存生产序列</h3><button v-for="record in records" class="record" @click="selected=record">{{record.created}} · {{record.rows.length}}小时 · {{record.id.slice(0,8)}}</button><SeriesPreview :csv="selected?.csv||csv"/><template v-if="selected"><p>{{selected.scope}}</p><p v-if="selected.embedded_scenario_id">绑定故障场景 {{selected.embedded_scenario_id.slice(0,8)}}；应用时与源荷一同载入。</p><details v-if="selected.coupled_event_rows"><summary>预览事件耦合容量</summary><div class="scroll"><table><tr><th>时间（原事件）</th><th>电网 / kW</th><th>应急发电 / kW</th><th>储能 / kW</th><th>风光 / kW</th></tr><tr v-for="row in selected.coupled_event_rows"><td>{{row.timestamp}}</td><td>{{row.available_kw_grid_channel}}</td><td>{{row.available_kw_emergency_gen}}</td><td>{{row.available_kw_storage}}</td><td>{{row.available_kw_renewable}}</td></tr></table></div></details><p>事件区间 {{selected.event_start}} 至 {{selected.event_end}}，共{{selected.rows.filter((row:any)=>row.is_extreme_condition).length}}小时。平滑{{selected.parameters.smooth?'已开启':'未开启'}}。</p><div class="actions"><button @click="emit('apply',selected.csv,selected.id,selected.embedded_scenario_id)">{{draftMode?'选用生产序列到草稿':'将生产序列应用到当前工程'}}</button><button @click="download">导出完整输入与序列快照</button></div><p>应用将替换当前源荷；耦合序列同时应用其故障场景，纯源荷序列解除旧场景。请重新核对运行阶段并计算。</p><details><summary>预览生产序列（前168小时）</summary><div class="scroll"><table><tr><th>时间</th><th>负荷 / kW</th><th>风电 / kW</th><th>光伏 / kW</th><th>事件标记</th></tr><tr v-for="row in selected.rows.slice(0,168)"><td>{{row.timestamp}}</td><td>{{row.load_kw}}</td><td>{{row.wind_kw}}</td><td>{{row.pv_kw}}</td><td>{{row.is_extreme_condition?'事件':'背景'}}</td></tr></table></div></details></template></article></template>
